namespace InventoryApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using InventoryApp.Models;

namespace InventoryApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a realistic async data fetch
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift A",        Location = "Warehouse 1", LastInspected = new DateTime(2026, 6, 10) },
            new() { Id = 2, Name = "Conveyor Belt B",   Location = "Warehouse 2", LastInspected = new DateTime(2026, 5, 22) },
            new() { Id = 3, Name = "Pallet Jack C",     Location = "Warehouse 1", LastInspected = new DateTime(2026, 7, 1) },
            new() { Id = 4, Name = "Crane D",           Location = "Yard",        LastInspected = new DateTime(2026, 4, 15) },
            new() { Id = 5, Name = "Compressor E",      Location = "Maintenance", LastInspected = new DateTime(2026, 3, 28) },
            new() { Id = 6, Name = "Generator F",       Location = "Yard",        LastInspected = new DateTime(2026, 6, 30) },
            new() { Id = 7, Name = "Welding Station G", Location = "Shop Floor",  LastInspected = new DateTime(2026, 2, 14) },
            new() { Id = 8, Name = "Drill Press H",     Location = "Shop Floor",  LastInspected = new DateTime(2026, 7, 8) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Models
@using InventoryApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState PersistState
@implements IDisposable

<PageTitle>Equipment Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        // Register a callback so the prerender pass persists data before the
        // HTML is sent.  On the interactive re-init this is a no-op because the
        // data is already restored below.
        _subscription = PersistState.RegisterOnPersisting(PersistData);

        // Try to restore data that was persisted during prerendering.
        // If it exists, skip the service call entirely (no double fetch).
        if (PersistState.TryTakeFromJson<List<EquipmentItem>>("equipment", out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        PersistState.PersistAsJson("equipment", _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

